from collections import Counter

type_pattern = []
for br in range(3):
    row_list = []
    for bc in range(3):
        rows_start = br * 4
        cols_start = bc * 4
        inner_block = [grid[rows_start+i][cols_start+j] for i in range(4) for j in range(4)]

        non_bg_counts = Counter(val for val in inner_block if val != 5)
        if non_bg_counts:
            row_list.append({
                'colors': len(non_bg_counts),
                'counts': dict(non_bg_counts),
                'total_cells': sum(non_bg_counts.values()),
                'most_common': max(non_bg_counts, key=non_bg_counts.get)
            })
        else:
            row_list.append('empty')
    type_pattern.append(row_list)

print("Type pattern per block (using most_common color):")
for r in type_pattern:
    print([x['most_common'] if isinstance(x, dict) else '.' for x in r])

